<?php
declare(strict_types=1);
function crmTransaction(PDO $db,callable $fn): mixed {$db->beginTransaction();try{$result=$fn();$db->commit();return $result;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
function crmNote(PDO $db,array $actor,string $entity,string $id,array $b): array {
 crmPermit($actor,'note.create');crmEntity($db,$entity,$id);$body=trim((string)($b['body']??''));if(mb_strlen($body)<1||mb_strlen($body)>4000||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f]/u',$body))throw new CrmError('INVALID_NOTE');$key=crmRequestId($b['request_id']??null);
 return crmTransaction($db,function()use($db,$actor,$entity,$id,$body,$key){$old=crmOne($db,'SELECT * FROM rubizh_internal_notes WHERE request_id=?',[$key]);if($old){if($old['entity']!==$entity||$old['entity_id']!==$id||$old['body']!==$body||$old['author_id']!==$actor['id'])throw new CrmError('IDEMPOTENCY_CONFLICT',409);return $old;}$db->prepare('INSERT INTO rubizh_internal_notes(entity,entity_id,author_id,body,request_id,created_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP())')->execute([$entity,$id,$actor['id'],$body,$key]);$note=(int)$db->lastInsertId();crmAudit($db,$actor,$entity,$id,'note.append',[],['note_id'=>$note,'body'=>$body],'',$key);return crmOne($db,'SELECT * FROM rubizh_internal_notes WHERE id=?',[$note]);});
}
function crmAssign(PDO $db,int $id,array $actor,array $b): array {
 crmPermit($actor,'order.assign.self');$target=$b['staff_id']??$actor['id'];if($target!==null&&$target!==$actor['id'])crmPermit($actor,'order.assign.any');if($target!==null&&!crmOne($db,"SELECT id FROM rubizh_staff_users WHERE id=? AND enabled=1 AND role IN ('OWNER','MANAGER')",[$target]))throw new CrmError('INVALID_ASSIGNEE');
 return npLocked($db,$id,function()use($db,$id,$actor,$b,$target){$old=crmOrder($db,$id);crmCheckVersion($old,$b);crmTransaction($db,function()use($db,$id,$actor,$target,$old){$db->prepare('INSERT INTO rubizh_order_assignments(order_id,staff_id,assigned_by,updated_at) VALUES(?,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE staff_id=VALUES(staff_id),assigned_by=VALUES(assigned_by),updated_at=VALUES(updated_at)')->execute([$id,$target,$actor['id']]);crmAudit($db,$actor,'order',(string)$id,'order.assign',['manager'=>$old['assigned_manager']],['staff_id'=>$target]);});return crmOrder($db,$id);});
}
function crmOrderAction(PDO $db,int $id,array $actor,array $b,string $action): array {
 $permission=['confirm'=>'order.confirm','resolve-item'=>'order.confirm','cancel'=>'order.cancel','invoice'=>'payment.invoice.create','manual-reconcile'=>'payment.manual_reconcile'][$action]??null;if(!$permission)throw new CrmError('NOT_FOUND',404);crmPermit($actor,$permission);
 return npLocked($db,$id,function()use($db,$id,$actor,$b,$action){$old=crmOrder($db,$id);crmCheckVersion($old,$b);
 if(in_array($action,['confirm','resolve-item'],true)){$GLOBALS['rubizh_request_resolution']=is_array($b['resolution']??null)?$b['resolution']:[];npConfirm($db,$id,$actor['id'],($b['availability_confirmed']??false)===true,($b['extra_delivery_agreed']??false)===true,(string)($b['payment_proof']??''),is_array($b['approval']??null)?$b['approval']:[]);}
 elseif($action==='cancel')shopCancelOrder($db,$id);
 elseif($action==='invoice'){if($old['order_status']!=='CONFIRMED')throw new CrmError('CONFIRMATION_REQUIRED',409);$invoice=monoCreate($db,$id,$actor['id']);}
 elseif($action==='manual-reconcile')monoReconcile($db,$id,(string)($b['invoice_id']??''),$actor['id'],(string)($b['reason']??''));
 $new=crmOrder($db,$id);crmAudit($db,$actor,'order',(string)$id,'order.'.$action,['version'=>$old['version'],'total'=>$old['total']],['version'=>$new['version'],'total'=>$new['total']],(string)($b['reason']??$b['approval']['reason']??''));return $new+['invoice'=>$invoice??null];});
}
function crmReturnCreate(PDO $db,array $actor,array $b): array {
 crmPermit($actor,'return.create');$order=(int)($b['order_id']??0);$key=crmRequestId($b['request_id']??null);$reason=shopFinancialReason((string)($b['reason']??''));
 return npLocked($db,$order,function()use($db,$order,$actor,$b,$key,$reason){crmScopeWrite(crmOrder($db,$order),$actor);$old=crmOne($db,'SELECT * FROM rubizh_returns WHERE request_id=?',[$key]);if($old){if((int)$old['order_id']!==$order||$old['created_by']!==$actor['id']||array_map(fn($l)=>array_intersect_key($l,array_flip(['line_no','qty'])),json_decode($old['lines_json'],true))!==($b['lines']??[]))throw new CrmError('IDEMPOTENCY_CONFLICT',409);return $old;}$o=crmOrder($db,$order,[]);crmCheckVersion($o,$b);if(!in_array($o['payment_status'],['PAID','PARTIALLY_REFUNDED','REFUNDED'],true))throw new CrmError('PAID_ORDER_REQUIRED',409);$lines=$b['lines']??[];if(!is_array($lines)||!$lines)throw new CrmError('INVALID_RETURN_LINES');$held=[];$heldMinor=[];foreach($o['returns'] as $r)if($r['state']!=='REJECTED')foreach(json_decode($r['lines_json'],true) as $l){if(!isset($l['refund_minor']))throw new CrmError('RETURN_VALUE_REVIEW_REQUIRED',409);$held[$l['line_no']]=($held[$l['line_no']]??0)+(float)$l['qty'];$heldMinor[$l['line_no']]=($heldMinor[$l['line_no']]??0)+(int)$l['refund_minor'];}$seen=[];$expected=0;
 foreach($lines as &$l){if(!is_array($l)||array_diff(array_keys($l),['line_no','qty']))throw new CrmError('INVALID_RETURN_LINES');$no=$l['line_no']??null;if(!is_int($no)||isset($seen[$no])||!isset($o['items'][$no]))throw new CrmError('INVALID_RETURN_LINES');$seen[$no]=true;$qty=shopQuantity($l['qty']??null,$o['items'][$no]['sale_unit']??'piece');if($qty+($held[$no]??0)>(float)$o['items'][$no]['qty'])throw new CrmError('RETURN_QUANTITY_EXCEEDED',409);$financial=null;foreach($o['fulfillment_lines'] as $f)if((int)$f['line_no']===$no)$financial=$f;if(!$financial||$financial['line_amount']===null)throw new CrmError('RETURN_VALUE_REVIEW_REQUIRED',409);$l['refund_minor']=crmReturnLineValue($financial,$qty,$held[$no]??0,$heldMinor[$no]??0);$expected+=$l['refund_minor'];}unset($l);
 return crmTransaction($db,function()use($db,$order,$actor,$key,$reason,$lines,$expected){$db->prepare("INSERT INTO rubizh_returns(order_id,state,lines_json,reason,refund_expected_minor,created_by,request_id,created_at,updated_at) VALUES(?,'REQUESTED',?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())")->execute([$order,json_encode($lines,JSON_THROW_ON_ERROR),$reason,$expected,$actor['id'],$key]);$id=(int)$db->lastInsertId();crmAudit($db,$actor,'return',(string)$id,'return.request',[],['order_id'=>$order,'lines'=>$lines,'state'=>'REQUESTED'],$reason,$key);return crmOne($db,'SELECT * FROM rubizh_returns WHERE id=?',[$id]);});});
}
function crmReturnTransition(PDO $db,int $id,array $actor,array $b): array {
 $r=crmOne($db,'SELECT * FROM rubizh_returns WHERE id=?',[$id]);if(!$r)throw new CrmError('NOT_FOUND',404);
 crmScopeWrite(crmOrder($db,(int)$r['order_id']),$actor);
 return npLocked($db,(int)$r['order_id'],function()use($db,$id,$actor,$b){return crmTransaction($db,function()use($db,$id,$actor,$b){$r=crmOne($db,'SELECT * FROM rubizh_returns WHERE id=? FOR UPDATE',[$id]);if((int)($b['version']??0)!==(int)$r['version'])throw new CrmError('STALE_ORDER',409);$next=(string)($b['state']??'');$allowed=['REQUESTED'=>['APPROVED','REJECTED'],'APPROVED'=>['IN_TRANSIT','RECEIVED'],'IN_TRANSIT'=>['RECEIVED'],'RECEIVED'=>['REFUND_PENDING','CLOSED'],'REFUND_PENDING'=>['CLOSED']][$r['state']]??[];if($next==='REFUND_PENDING'&&(int)$r['refund_expected_minor']===0)throw new CrmError('ZERO_VALUE_PHYSICAL_RETURN',409);if(!in_array($next,$allowed,true))throw new CrmError('INVALID_STATE_TRANSITION',409);if(!crmCan($actor,'return.review')&&!in_array($next,['IN_TRANSIT','RECEIVED'],true))throw new CrmError('PERMISSION_DENIED',403);
 $reason=shopFinancialReason((string)($b['reason']??''));$tracking=(string)($b['tracking_number']??$r['tracking_number']);if($tracking!==''&&!preg_match('/^\d{14}$/D',$tracking))throw new CrmError('INVALID_TRACKING_NUMBER');$decision=(string)($b['inventory_decision']??$r['inventory_decision']);if($decision!==$r['inventory_decision']){crmPermit($actor,'inventory.return');if(!in_array($decision,['KEEP_COMMITTED','PIM_RECONCILIATION_REQUIRED'],true))throw new CrmError('INVALID_INVENTORY_DECISION');}
 if($next==='CLOSED'&&$decision==='PENDING')throw new CrmError('INVENTORY_DECISION_REQUIRED',409);$allocations=json_decode($r['refund_allocations_json']??'null',true);if($next==='CLOSED'&&$r['state']==='REFUND_PENDING'){
 crmPermit($actor,'payment.refund.execute');$allocations=$b['refund_allocations']??[];if(!is_array($allocations)||!$allocations||count($allocations)>100)throw new CrmError('REFUND_EVIDENCE_REQUIRED',409);$used=[];foreach(crmQuery($db,'SELECT refund_allocations_json FROM rubizh_returns WHERE order_id=? AND id<>? FOR UPDATE',[$r['order_id'],$id]) as $other)foreach(json_decode($other['refund_allocations_json']??'null',true)??[] as $a)$used[$a['refund_id']]=($used[$a['refund_id']]??0)+(int)$a['amount'];$seen=[];$amount=0;foreach($allocations as $a){if(!is_int($a['refund_id']??null)||isset($seen[$a['refund_id']])||!is_int($a['amount']??null)||$a['amount']<=0)throw new CrmError('INVALID_REFUND_ALLOCATION',409);$seen[$a['refund_id']]=true;$op=crmOne($db,"SELECT * FROM rubizh_refund_operations WHERE id=? AND order_id=? AND status='success' FOR UPDATE",[$a['refund_id'],$r['order_id']]);if(!$op||$a['amount']+($used[$a['refund_id']]??0)>(int)$op['amount'])throw new CrmError('REFUND_EVIDENCE_REQUIRED',409);$amount+=$a['amount'];}if($amount!==(int)$r['refund_expected_minor'])throw new CrmError('REFUND_AMOUNT_MISMATCH',409);
 }

 $db->prepare('UPDATE rubizh_returns SET state=?,tracking_number=?,inventory_decision=?,inventory_evidence=?,refund_allocations_json=?,version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=?')->execute([$next,$tracking,$decision,(string)($b['inventory_evidence']??$r['inventory_evidence']),$allocations===null?null:json_encode($allocations,JSON_THROW_ON_ERROR),$id]);crmAudit($db,$actor,'return',(string)$id,'return.transition',$r,['state'=>$next,'tracking_number'=>$tracking,'inventory_decision'=>$decision,'refund_allocations'=>$allocations],$reason);return crmOne($db,'SELECT * FROM rubizh_returns WHERE id=?',[$id]);});});
}
function crmSenderComplete(array $p): bool {return npSenderProfileComplete($p);}
function crmSenderSave(PDO $db,string $code,array $actor,array $b): array {
 crmPermit($actor,'supplier.manage');$reason=shopFinancialReason((string)($b['reason']??''));$old=crmOne($db,'SELECT * FROM rubizh_sender_profiles WHERE code=?',[$code]);if(!$old)throw new CrmError('NOT_FOUND',404);if((int)$old['version']!==(int)($b['version']??0))throw new CrmError('STALE_ORDER',409);$fields=['name','city','region','branch','cargo_branch','city_ref','warehouse_ref','cargo_warehouse_ref','sender_ref','contact_ref','phone','confirmed'];$new=$old;foreach($fields as $f)if(array_key_exists($f,$b))$new[$f]=$f==='confirmed'?(int)($b[$f]===true):(string)$b[$f];foreach($new as $k=>$v)if(is_string($v)&&strlen($v)>400)throw new CrmError('INVALID_PROFILE');foreach(['city_ref','warehouse_ref','cargo_warehouse_ref','sender_ref','contact_ref'] as $f)if($new[$f]!==''&&!npRef($new[$f]))throw new CrmError('INVALID_NP_REF');if($new['confirmed']&&!crmSenderComplete($new))throw new CrmError('SENDER_PROFILE_INCOMPLETE',409);
 return crmTransaction($db,function()use($db,$code,$actor,$new,$old,$fields,$reason,$b){$q=$db->prepare('UPDATE rubizh_sender_profiles SET '.implode(',',array_map(fn($f)=>"$f=?",$fields)).',version=version+1,updated_by=?,updated_at=UTC_TIMESTAMP() WHERE code=? AND version=?');$q->execute([...array_map(fn($f)=>$new[$f],$fields),$actor['id'],$code,$old['version']]);if(!$q->rowCount())throw new CrmError('STALE_ORDER',409);
 if((array_key_exists('contact_person',$b)||array_key_exists('prep_days',$b))&&crmApiTableExists($db,'rubizh_crm_supplier_info'))$db->prepare('INSERT INTO rubizh_crm_supplier_info(code,contact_person,prep_days,updated_by,updated_at) VALUES(?,?,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE contact_person=VALUES(contact_person),prep_days=VALUES(prep_days),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)')->execute([$code,mb_substr(trim((string)($b['contact_person']??'')),0,120),isset($b['prep_days'])?(int)$b['prep_days']:null,$actor['id']]);
 crmAudit($db,$actor,'sender',$code,'sender.update',$old,array_intersect_key($new,array_flip($fields))+array_intersect_key($b,array_flip(['contact_person','prep_days'])),$reason);return crmOne($db,'SELECT * FROM rubizh_sender_profiles WHERE code=?',[$code]);});
}
function crmConfigureSender(PDO $db,string $code): void {try{npUseSenderProfile($db,$code);}catch(ShopOrderConflict $e){throw new CrmError('SENDER_PROFILE_INCOMPLETE',409,['supplier'=>$code]);}}
function crmShipmentAction(PDO $db,int $order,array $actor,array $b,string $action,?int $shipment=null): array {
 crmPermit($actor,'shipment.manage');return npLocked($db,$order,function()use($db,$order,$actor,$b,$action,$shipment){$old=crmOrder($db,$order,[]);crmScopeWrite($old,$actor); // R4-03; S4-06: full order for the checks
 if($action==='manual')return crmManualTtn($db,$order,$actor,$b,$old);
 if($action==='draft'){$existing=crmOne($db,'SELECT * FROM rubizh_order_shipments WHERE operation_key=?',[$b['request_id']??'']);if($existing){$allocation=array_map(fn($l)=>['line_no'=>(int)$l['line_no'],'qty'=>(float)$l['qty']],json_decode($existing['lines_json'],true));$input=array_map(fn($l)=>['line_no'=>(int)($l['line_no']??-1),'qty'=>(float)($l['qty']??0)],$b['lines']??[]);if((int)$existing['order_id']!==$order||$existing['supplier_code']!==($b['supplier_code']??'')||$allocation!==$input||npPackage(json_decode($existing['package_json'],true))!==npPackage($b['package']??[]))throw new CrmError('IDEMPOTENCY_CONFLICT',409);return crmOrder($db,$order,$actor);}if(!in_array($old['payment_status'],['PAID','PARTIALLY_REFUNDED'],true))throw new CrmError('PAID_ORDER_REQUIRED',409);}
 crmCheckVersion($old,$b);
 if($action==='draft'){$id=crmTransaction($db,function()use($db,$order,$actor,$b){crmConfirmPacking($db,$order,$actor,$b);return npDraft($db,$order,$actor['id'],crmRequestId($b['request_id']??null),(string)($b['supplier_code']??''),is_array($b['lines']??null)?$b['lines']:[],is_array($b['package']??null)?$b['package']:[]);});}
 else{$s=crmOne($db,'SELECT * FROM rubizh_order_shipments WHERE id=? AND order_id=?',[$shipment,$order]);if(!$s)throw new CrmError('NOT_FOUND',404);if($action==='create'){crmConfigureSender($db,$s['supplier_code']);try{npCreate($db,$order,(int)$shipment,$actor['id']);}finally{unset($GLOBALS['crm_domain_config']);}}elseif($action==='refresh')npRefresh($db,$order,$actor['id']);elseif($action==='reconcile')npReconcile($db,$order,(int)$shipment,$actor['id']);elseif($action==='cancel')npCancelDraft($db,$order,(int)$shipment,$actor['id']);else throw new CrmError('NOT_FOUND',404);}
 $new=crmOrder($db,$order);crmAudit($db,$actor,'order',(string)$order,'shipment.'.$action,['version'=>$old['version']],['version'=>$new['version'],'shipment_id'=>$id??$shipment]);return $new;});
}

/** «Фактичну наявність і комплектацію перевірено» sent with a new parcel (draft or manual TTN). */
function crmConfirmPacking(PDO $db,int $order,array $actor,array $b): void {
 if(($b['availability_confirmed']??false)===true){$old=crmOne($db,'SELECT * FROM rubizh_np_order_confirmations WHERE order_id=?',[$order]);$extra=($b['extra_delivery_agreed']??false)===true;$db->prepare('INSERT INTO rubizh_np_order_confirmations(order_id,availability_confirmed,extra_delivery_agreed,confirmed_at,confirmed_by,updated_at) VALUES(?,1,?,UTC_TIMESTAMP(),?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE availability_confirmed=1,extra_delivery_agreed=IF(VALUES(extra_delivery_agreed)=1,1,extra_delivery_agreed),confirmed_by=VALUES(confirmed_by),updated_at=UTC_TIMESTAMP()')->execute([$order,(int)$extra,$actor['id']]);crmAudit($db,$actor,'order',(string)$order,'shipment.packing_confirm',$old??[],['availability_confirmed'=>true,'extra_delivery_agreed'=>$extra],'Фактичну наявність і комплектацію перевірено');}
}
/** Stage 5.6-2 (D-83): «Внести ТТН вручну» — a TTN created outside CRM (another NP cabinet), entered by staff. */
function crmManualTtn(PDO $db,int $order,array $actor,array $b,array $old): array {
 try{$number=npTrackingNumber((string)($b['tracking_number']??''));}catch(InvalidArgumentException $e){throw new CrmError('TTN_FORMAT_INVALID',422);}
 $existing=crmOne($db,'SELECT * FROM rubizh_order_shipments WHERE operation_key=?',[$b['request_id']??'']);
 if($existing){if((int)$existing['order_id']!==$order||$existing['tracking_number']!==$number)throw new CrmError('IDEMPOTENCY_CONFLICT',409);return crmOrder($db,$order,$actor);}
 if(!in_array($old['payment_status'],['PAID','PARTIALLY_REFUNDED'],true))throw new CrmError('PAID_ORDER_REQUIRED',409);
 crmCheckVersion($old,$b);
 $id=crmTransaction($db,function()use($db,$order,$actor,$b,$number){crmConfirmPacking($db,$order,$actor,$b);
  try{return npManualShipment($db,$order,$actor['id'],crmRequestId($b['request_id']??null),is_array($b['lines']??null)?$b['lines']:[],$number);}catch(NpTrackingNumberUsed $e){throw new CrmError('TTN_ALREADY_USED',409);}});
 $new=crmOrder($db,$order);crmAudit($db,$actor,'order',(string)$order,'shipment.manual_ttn',['version'=>$old['version']],['version'=>$new['version'],'shipment_id'=>$id,'tracking_number'=>$number]);return $new;
}

/** Allocate rounding remainder to the final physical quantity, in integer minor units. */
function crmReturnLineValue(array $line,int|float $qty,int|float $heldQty,int $heldMinor): int {
 if($line['line_amount']===null||(float)$line['qty']<=0)throw new CrmError('RETURN_VALUE_REVIEW_REQUIRED',409);$total=(int)round((float)$line['line_amount']*100);$leftQty=(float)$line['qty']-$heldQty;$left=$total-$heldMinor;if($qty>$leftQty+0.00001||$left<0)throw new CrmError('RETURN_QUANTITY_EXCEEDED',409);$amount=abs($qty-$leftQty)<0.00001?$left:(int)round($total*$qty/(float)$line['qty']);if($amount>$left)throw new CrmError('RETURN_VALUE_REVIEW_REQUIRED',409);return $amount;
}
